fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        // Use mid calculation that avoids overflow
        let mid = left + (right - left) / 2;
        let mid_val = v[mid];

        if mid_val == k {
            return mid;
        } else if mid_val < k {
            left = mid + 1;
        } else {
            // mid_val > k
            // Prevent underflow when mid == 0 (but since k appears at least once,
            // and mid_val > k means search left side)
            if mid == 0 {
                break; // can't reduce further, target not found which violates assumption
            }
            right = mid - 1;
        }
    }

    // According to problem statement, k appears at least once,
    // so we should never reach here.
    unreachable!("The target k is guaranteed to appear in the array");
}